import 'package:flutter/material.dart';

abstract class AppThemeEvent {
  const AppThemeEvent();
}

class ChangeThemeModeEvent extends AppThemeEvent {
  final ThemeMode themeMode;
  const ChangeThemeModeEvent(this.themeMode);
}

class ChangeAccentColorEvent extends AppThemeEvent {
  final Color accentColor;
  const ChangeAccentColorEvent(this.accentColor);
}

/// Applies the palettes generated by the `org.rde.Theme` service.
///
/// The schemes come from the theme service, so the settings app renders the
/// same colors as the rest of the desktop. [sourceColorArgb] keeps the seed
/// color available for swatches that do not read the full palette.
class ApplySystemPaletteEvent extends AppThemeEvent {
  const ApplySystemPaletteEvent({
    required this.lightScheme,
    required this.darkScheme,
    required this.sourceColorArgb,
    required this.isDark,
  });

  final ColorScheme lightScheme;
  final ColorScheme darkScheme;
  final int sourceColorArgb;
  final bool isDark;
}
